begin;
insert into academy_private.audit_log(actor_id,action,target,details) select auth.uid(),'manager_first_three_before','guru-42932',jsonb_build_object('payload',payload,'updated_at',updated_at) from public.academy_content where id='guru-42932';
with incoming as(select value from jsonb_array_elements('[{"id":"123885","title":"🎓КЛН МЕНЕДЖЕРА — Контрольный лист наблюдения","blocks":[{"id":"manager-layout-1","type":"hero","label":"Стажировка менеджера · 90-е","title":"КЛН МЕНЕДЖЕРА — Контрольный лист наблюдения","image":"assets/remaining-courses/guru-42932-123885-0.jpg","tone":"sky"},{"id":"manager-layout-2","type":"callout","title":"Цель занятия","text":"понять, по каким критериям оценивается работа менеджера, и к чему стремиться.","tone":"sky"},{"id":"manager-layout-3","type":"heading","text":"📋 Что такое КЛН","level":2},{"id":"manager-layout-4","type":"text","html":"<p>КЛН (Контрольный лист наблюдения) — это свод стандартов, по которым оценивается работа менеджера. Это твой навигатор в мире профессионального управления.</p>"},{"id":"manager-layout-5","type":"heading","text":"Зачем он нужен","level":3},{"id":"manager-layout-6","type":"list","items":["Ты видишь чёткие критерии оценки.","Понимаешь, на что обращают внимание управляющий и наставник.","Можешь самостоятельно оценивать свой прогресс.","Знаешь, к чему стремиться."],"ordered":false},{"id":"manager-layout-7","type":"link","text":"Скачать КЛН","url":"https://docs.google.com/spreadsheets/d/19k74sIGUt0vedhwkBGlWKp8A6RRQeVz6IDJcvA-ogiQ/edit?gid=0#gid=0"},{"id":"manager-layout-8","type":"heading","text":"⭐ Как оцениваются критерии","level":2},{"id":"manager-layout-9","type":"text","html":"<p>Каждый пункт оценивается по простой шкале:</p><p>Выполнено: Соответствует стандарту, всё сделано правильно</p><p>Частично: Есть мелкие недочёты, но в целом выполнено</p><p>Не выполнено: Не сделано или выполнено с грубыми ошибками</p>"},{"id":"manager-layout-10","type":"callout","title":"Порог КЛН","text":"85% — минимальный процент выполнения для успешного прохождения аттестации.","tone":"yellow"},{"id":"manager-layout-11","type":"list","items":["100%: Отлично! Ты готов к самостоятельной работе","85% и выше: Проходной балл, ты справляешься со стандартами","Ниже 85%: Нужно доработать. На KPI пока не рассчитывай, требуется дополнительное обучение"],"ordered":false},{"id":"manager-layout-12","type":"heading","text":"📝 Полный список критериев КЛН менеджера","level":2},{"id":"manager-layout-13","type":"heading","text":"1️⃣ Работа с персоналом и готовность зала","level":3},{"id":"manager-layout-14","type":"list","items":["1.1. Все сотрудники прибыли вовремя на работу.","1.2. Внешний вид персонала соответствует стилю 90-х.","1.3. Проведено собрание с персоналом в 17:45 (озвучены все насущные вопросы: отзывы, конкурс, итд). Напоминание про карту лояльности: перед расчётом официант уточняет, зарегистрирован ли гость в системе лояльности. Если да — берёт номер карты, если нет — регистрирует.","1.4. Все сотрудники знают актуальные акции и предложения.","1.5. Проведена проверка знаний акций и будущих мероприятий.","1.6. Проверена чистота входной зоны.","1.7. Все туалеты чистые (унитазы, раковины, зеркала, расходники пополнены).","1.8. Протёрт весь декор (пыль, чистота фигур, фотозон и пр.).","1.9. Чистота барной стойки проверена, маркировка продукции актуальна.","1.10. Полностью готово заведение к открытию (чистота зала, столов, мебели).","1.11. Освещение и звук входной группы исправны и работают в штатном режиме в 17:50 включено.","1.12. Освещение залов работает корректно согласно времени суток."],"ordered":false},{"id":"manager-layout-15","type":"heading","text":"2️⃣ Работа с таблицами бронирования/заявок/предоплат","level":3},{"id":"manager-layout-16","type":"list","items":["2.1. Разобраны все входящие заявки по броням.","2.2. Проведена актуализация всех броней (связались с гостями, подтвердили).","2.3. Все брони подтверждены (гости внесли предоплату).","2.4. Неподтверждённые брони: указана причина и снесены в отмены.","2.5. Сделаны предзаказы по мероприятиям для компаний от 6 человек.","2.6. Предзаказы отмечены в таблице бронирования.","2.7. Предзаказы переданы на кухню (шеф поставлен в известность).","2.8. Предзаказы отправлены в рабочий чат «Предзаказы».","2.9. Сверены все предоплаты с отметками в таблицах бронирования и предоплат.","2.10. Предоплаты по Eat&Split внесены в систему iiko."],"ordered":false},{"id":"manager-layout-17","type":"heading","text":"3️⃣ Документооборот и отчёты","level":3},{"id":"manager-layout-18","type":"list","items":["3.1. В сводной таблице по поиску персонала заведены все комментарии по кандидатам, записанным на собеседование.","3.2. В таблице «Персонал» все сотрудники действующие.","3.3. У всех действующих сотрудников актуальные медицинские книжки.","3.4. В чат «Штат» отправлены дни рождения сотрудников следующего месяца (раз в месяц, 28 числа)."],"ordered":false},{"id":"manager-layout-19","type":"heading","text":"4️⃣ Склад, хозчасть и чистота заведения","level":3},{"id":"manager-layout-20","type":"list","items":["4.1. Проверено наличие всех необходимых хозяйственных товаров (хозы).","4.2. Заказаны недостающие хозтовары (идентичны предыдущим заказам).","4.3. Всё оборудование и техника в рабочем состоянии.","4.4. Составлен список на ремонт или замену плитки/мебели/оборудования (информация отправлена в чат «ремонт» или «технический»).","4.5. Заказана или проведена дезинсекция от насекомых (в случае необходимости)."],"ordered":false},{"id":"manager-layout-21","type":"heading","text":"5️⃣ Защита KPI (оценивает управляющий)","level":3},{"id":"manager-layout-22","type":"list","items":["5.1. Приём предзаказов.","5.2. Знание актуальных акций.","5.3. Депозитная система бара.","5.4. Презентация бара.","5.5. Знание формы отчёта хостес.","5.6. Проведение собеседований.","5.7. Закрытие столов и предоплаты.","5.8. Работа с кассой и депозитами в выходные."],"ordered":false},{"id":"manager-layout-23","type":"heading","text":"🚀 Как использовать КЛН в стажировке","level":2},{"id":"manager-layout-24","type":"list","items":["В начале курса: Прочитай все пункты, чтобы понимать, к чему мы идём.","В каждой смене: Наставник может давать отсылки к КЛН.","Наблюдай за наставником: Отмечай, как он выполняет те или иные пункты.","В конце смены: Попроси наставника предварительно оценить тебя по 2–3 пунктам.","Перед финальной аттестацией: Повтори все пункты — это будет твой финальный экзамен."],"ordered":false},{"id":"manager-layout-25","type":"heading","text":"❗ Важные моменты из КЛН, которые нужно запомнить","level":2},{"id":"manager-layout-26","type":"list","items":["Про карту лояльности: Перед расчётом официант уточняет: «Вы зарегистрированы в нашей системе лояльности?» Если да — фотографирует карту. Если нет — регистрирует.","Про предзаказы: Компании от 6 человек — обязательный предзаказ. Предзаказы отмечаются в таблице бронирования, передаются на кухню и отправляются в чат «Предзаказы».","Про проверку предоплат: Сверка предоплат с отметками в таблицах бронирования и предоплат. Предоплаты по Eat&Split вносятся в iiko.","Про чистоту и готовность: В 17:50 должно быть включено освещение и звук входной группы. Освещение залов должно работать корректно согласно времени суток."],"ordered":false},{"id":"manager-layout-27","type":"heading","text":"🤔 Вопросы для самоанализа","level":2},{"id":"manager-layout-28","type":"text","html":"<p>В конце каждого дня (или в конце стажировки) задай себе эти вопросы:</p>"},{"id":"manager-layout-29","type":"list","items":["1. С какими ошибками я сталкиваюсь при работе с кассой и депозитами? Записывай, чтобы не повторять.","2. На какие аспекты мне нужно больше внимания или обучения? Честно отмечай слабые места и обсуждай с наставником."],"ordered":false},{"id":"manager-layout-30","type":"heading","text":"💡 Финальный совет","level":2},{"id":"manager-layout-31","type":"text","html":"<p>КЛН — это не инструмент наказания. Это твой навигатор.</p><p>Он показывает, куда двигаться, чтобы стать профессионалом. Не бойся низких оценок в начале — это нормально. Главное — видеть свои зоны роста и работать над ними.</p>"},{"id":"manager-layout-32","type":"heading","text":"Как использовать КЛН каждый день","level":3},{"id":"manager-layout-33","type":"list","items":["Перед сменой — вспомни ключевые критерии.","Во время смены — сверяй свои действия.","После смены — оцени себя по 2–3 пунктам.","Обсуждай с наставником, что получилось, а над чем работать.","Запомни: идеальных менеджеров не бывает, но есть те, кто постоянно растёт. Стремись к 100%, но не расстраивайся, если не дотягиваешь. Главное — прогресс."],"ordered":false},{"id":"manager-layout-34","type":"callout","title":"","text":"Ты справишься! 🔥","tone":"lilac"}]},{"id":"125255","title":"🎓 Портрет менеджера «Бара 90-е»","blocks":[{"id":"manager-layout-35","type":"hero","label":"Стажировка менеджера · 90-е","title":"Портрет менеджера «Бара 90-е»","image":"assets/remaining-courses/guru-42932-125255-0.jpg","tone":"sky"},{"id":"manager-layout-36","type":"callout","title":"Цель занятия","text":"понять, каким должен быть менеджер — внешне, внутренне и по ценностям.","tone":"sky"},{"id":"manager-layout-37","type":"heading","text":"Внешний образ","level":2},{"id":"manager-layout-38","type":"text","html":"<p>Менеджер «Бара 90-е» — это продолжение концепции. Он не просто надевает форму, он становится частью атмосферы.</p>"},{"id":"manager-layout-39","type":"heading","text":"Одежда","level":3},{"id":"manager-layout-40","type":"list","items":["Соответствует стилю заведения (утверждена форма либо дресс-код, отсылающий к эстетике 90-х)","Одежда чистая, выглаженная, без пятен и заломов","Обувь начищена"],"ordered":false},{"id":"manager-layout-41","type":"heading","text":"Аккуратность","level":3},{"id":"manager-layout-42","type":"list","items":["Волосы убраны или уложены","Руки ухоженные","Отсутствие яркого вызывающего макияжа/аксессуаров (если это не предусмотрено концепцией)","Отсутствие резких запахов (парфюм — нейтральный, без перегара и табака)","Ногти чистые, короткие"],"ordered":false},{"id":"manager-layout-43","type":"callout","title":"Гость должен понимать","text":"«Это главный». Внешний вид менеджера выделяет его среди команды, но не противопоставляет ей.","tone":"green"},{"id":"manager-layout-44","type":"table","title":"Манера держаться","headers":["Что","Как"],"rows":[["Осанка","Прямая, уверенная, без сутулости"],["Взгляд","Открытый, спокойный, сканирующий зал, но не «сканирующий» гостей как объекты"],["Жесты","Размеренные, без суеты. Менеджер не бегает — он идёт уверенным шагом"],["Улыбка","Уместная, искренняя. Не дежурная «американская», а живая"]]},{"id":"manager-layout-45","type":"heading","text":"Внутренние качества","level":2},{"id":"manager-layout-46","type":"heading","text":"Лидер, а не надсмотрщик","level":3},{"id":"manager-layout-47","type":"text","html":"<p>Менеджер не стоит над душой и не кричит. Он ведёт за собой.</p><p>Команда видит в нём опору, а не источник стресса.</p><p>В пиковые часы он не наблюдает — он подхватывает, помогает, организует.</p>"},{"id":"manager-layout-48","type":"heading","text":"Стрессоустойчивость и эмоциональный интеллект","level":3},{"id":"manager-layout-49","type":"text","html":"<p>В пятницу в 23:00, когда очередь на входе, на баре 20 чеков, а гость жалуется на время подачи — менеджер не паникует.</p>"},{"id":"manager-layout-50","type":"heading","text":"Он умеет","level":3},{"id":"manager-layout-51","type":"list","items":["отделять эмоции гостя от личных обид","сохранять спокойствие (его состояние транслируется на команду)","быстро принимать решения в нестандартных ситуациях"],"ordered":false},{"id":"manager-layout-52","type":"heading","text":"Ответственность и честность","level":3},{"id":"manager-layout-53","type":"text","html":"<p>Если есть расхождение в кассе — менеджер не прячет, а ищет причину.</p><p>Если ошибся — признаёт, разбирает, делает выводы.</p><p>Понимает: его зона ответственности — это не только атмосфера, но и деньги, и безопасность.</p>"},{"id":"manager-layout-54","type":"heading","text":"Внимание к деталям","level":3},{"id":"manager-layout-55","type":"text","html":"<p>Замечает, что на третьем столе закончились салфетки, до того как гость попросил.</p><p>Видит, что бармен забыл поменять маркировку.</p><p>Слышит, что музыка стала чуть громче обычного.</p><p>Для него «мелочей» не существует.</p>"},{"id":"manager-layout-56","type":"heading","text":"Обучаемость и обратная связь","level":3},{"id":"manager-layout-57","type":"text","html":"<p>Менеджер знает: он не знает всего.</p><p>Открыт к критике, не защищается, когда наставник указывает на ошибку.</p><p>Читает отчёты, анализирует, спрашивает: «А почему так лучше?»</p>"},{"id":"manager-layout-58","type":"heading","text":"Управленческая зрелость","level":3},{"id":"manager-layout-59","type":"text","html":"<p>Не делает работу за подчинённых, но знает, как делать.</p><p>Не перекладывает ответственность.</p><p>Умеет делегировать и доверять, но при этом контролировать результат.</p>"},{"id":"manager-layout-60","type":"heading","text":"Ценности и убеждения менеджера","level":2},{"id":"manager-layout-61","type":"table","title":"","headers":["Ценность","Как проявляется"],"rows":[["«Гость — главный, но не единственный»","Балансирует между «гость всегда прав» и «мои сотрудники — профессионалы». В конфликте — на стороне справедливости, а не слепого угодничества."],["«Сервис — это не действие, это состояние»","Умение предугадать желание, создать ощущение заботы, сделать так, чтобы гость ушёл с мыслью: «Я вернусь»."],["«Честность в деньгах — основа доверия»","Фанатично относится к кассовой дисциплине. Скидка 20%+ только наличными — не прихоть, а принцип. Знает: любая нечестность с деньгами разрушает бизнес."],["«Команда — это единый организм»","Не делит персонал на «своих» и «чужих». Официант, бармен, уборщица, охрана — все звенья одной цепи. Видит систему целиком."],["«90-е — это не декор, это эмоция»","Понимает: гость приходит за ностальгией, за драйвом, за ощущением «я в другом времени». Каждое решение работает на эту эмоцию."]]},{"id":"manager-layout-62","type":"heading","text":"Что менеджер НЕ должен делать (анти-портрет)","level":2},{"id":"manager-layout-63","type":"table","title":"","headers":["Действие","Почему это плохо"],"rows":[["Кричит на персонал","Уничтожает атмосферу в команде. Гости слышат. Это не лидерство, это слабость."],["Исчезает в пик","Менеджер в пик — в зале. Не в подсобке, не на телефоне, не на улице с сигаретой."],["Закрывает глаза на нарушения","Если на баре продукт без маркировки, а официант в грязной футболке — это ответственность менеджера."],["Перекладывает вину","«Это не я, это официант не донёс». Нет. За смену отвечает менеджер."],["Игнорирует обратную связь","Если гость пожаловался, а менеджер не сделал выводов — этот гость не вернётся."],["Не знает акций","Смертный грех. Гость спрашивает про скидку, менеджер «ээээ...» — доверие потеряно."],["Нарушает финансовые правила","Скидка 20%+ по карте, закрытие стола официантом — это не «мелочь», это нарушение, за которое увольняют."]]},{"id":"manager-layout-64","type":"heading","text":"Цели менеджера","level":2},{"id":"manager-layout-65","type":"heading","text":"Операционные цели (на смену)","level":3},{"id":"manager-layout-66","type":"text","html":"<p>Безупречная готовность: к 18:00 всё должно быть идеально</p><p>Выполнение плана продаж: знает план и работает на его выполнение</p><p>Соблюдение стандартов: ни одного нарушения в сервисе, чистоте, кассовой дисциплине</p><p>Ноль конфликтов: предотвращать или решать на ранней стадии</p><p>Чистое закрытие: отчёты без ошибок, касса сходится, зал готов к следующему дню</p>"},{"id":"manager-layout-67","type":"heading","text":"Управленческие цели (на месяц/квартал)","level":3},{"id":"manager-layout-68","type":"text","html":"<p>Развитие команды: видит, кто может вырасти, наставляет, даёт обратную связь</p><p>Стабильность KPI: стабильно держать оценку по КЛН не ниже 85%</p><p>Снижение текучки: через справедливое отношение, понятные задачи и уважение</p><p>Увеличение среднего чека: через грамотную работу официантов с акциями и картой лояльности</p>"},{"id":"manager-layout-69","type":"heading","text":"Личные цели (развитие)","level":3},{"id":"manager-layout-70","type":"text","html":"<p>Стать управляющим (для кого-то — следующая ступень)</p><p>Мастерство переговоров: работа со сложными гостями и конфликтами</p><p>Финансовая грамотность: от кассовых отчётов до понимания P&amp;L заведения</p><p>Экспертность в сервисе: стать тем, к кому приходят учиться</p>"}]},{"id":"123841","title":"🎓 Смена 1. «Че здесь происходит ваще?» — Погружение в проект","blocks":[{"id":"manager-layout-71","type":"hero","label":"Стажировка менеджера · 90-е","title":"Смена 1. «Че здесь происходит ваще?» — Погружение в проект","image":"assets/remaining-courses/guru-42932-123841-0.jpg","tone":"sky"},{"id":"manager-layout-72","type":"callout","title":"Цель занятия","text":"создать полное понимание работы заведения и ответить на вопрос «что здесь происходит вообще?».","tone":"sky"},{"id":"manager-layout-73","type":"heading","text":"👋 Твой первый день","level":2},{"id":"manager-layout-74","type":"text","html":"<p>Сегодня ты начинаешь путь в команду менеджеров. Твоя задача — не управлять, а смотреть, слушать и запоминать. Бар — это живой организм, и чтобы им управлять, нужно сначала понять, как он дышит.</p>"},{"id":"manager-layout-75","type":"heading","text":"📋 Что ты делаешь сегодня","level":2},{"id":"manager-layout-76","type":"list","items":["17:00 - Приходишь на стажировку (если есть мероприятия — приходим раньше)","17:45 — Посещаешь наше общее собрание персонала. Знакомишься с командой смены: официанты, бармены, хостес, охрана, уборщицы. Наблюдаешь, как проходит собрание, какие вопросы поднимаются.","📖 Знакомишься с брендом и концепцией «Бар 90-е». Это не просто бар — это машина времени.","🎯 Изучаешь обязанности менеджера по стандарту работы (кратко, без деталей — основная задача: понять масштаб ответственности).","🗺️ Ознакомление с пространством заведения:","Входная группа (главный вход, служебный вход)","Гардероб","Зона хостес","Зал (основные зоны, VIP, фотозоны)","Барная стойка","Кухня (без входа, просто расположение)","Туалеты","Технические помещения (склады, раздевалка, комната персонала)","📍 Выучить адрес, номер телефона, Wi-Fi заведения (гостевой и служебный).","🔔 Подписаться на Instagram, Telegram-канал заведения и канал Операционного Директора.","🚶 Изучение основных маршрутов сотрудников:","Вход сотрудников осуществляется через главный вход, который одновременно является зоной «суточного поста». Здесь ведется контроль времени прихода/ухода и досмотр персонала.","Официанты — от кухни/бара к столам, по определенным проходам.","Бармены — за стойкой, выход в зал при необходимости.","Хостес — от входа к столам и обратно.","Охрана — точка входа, патрулирование зала."],"ordered":false},{"id":"manager-layout-77","type":"heading","text":"✅ Задание на вечер","level":2},{"id":"manager-layout-78","type":"heading","text":"Выучить как свои пять пальцев","level":3},{"id":"manager-layout-79","type":"list","items":["Адрес заведения","Номер телефона бара","Wi-Fi пароль (гостевой и служебный)","Подписаться на Instagram и Telegram-канал заведения","Подписаться на канал Операционного Директора"],"ordered":false},{"id":"manager-layout-80","type":"heading","text":"💡 Финальный совет на смену","level":2},{"id":"manager-layout-81","type":"text","html":"<p>Сегодня ты не управляешь — ты впитываешь. Смотри, слушай, запоминай. Каждый сотрудник, каждая зона, каждый маршрут — часть большой системы. Чтобы управлять системой, нужно сначала понять, как она устроена.</p>"},{"id":"manager-layout-82","type":"callout","title":"","text":"Завтра — знакомство с функционалом каждой должности. Отдохни и наберись сил. 🔥","tone":"lilac"}]}]'::jsonb)), revised as(select jsonb_agg(case when i.value is not null then l.value||jsonb_build_object('blocks',i.value->'blocks') else l.value end order by l.n) as lessons from public.academy_content c cross join lateral jsonb_array_elements(c.payload->'lessons') with ordinality l(value,n) left join incoming i on i.value->>'id'=l.value->>'id' where c.id='guru-42932')
update public.academy_content c set payload=jsonb_set(c.payload,'{lessons}',revised.lessons),updated_at=clock_timestamp() from revised where c.id='guru-42932';
commit;
select id,jsonb_array_length(payload->'lessons') as lessons,(select count(*) from jsonb_array_elements(payload->'lessons') l where l ? 'blocks') as formatted from public.academy_content where id='guru-42932';
